def solve(X,y,weights,bias,lr=0.01,epochs=1):
    n=len(X); d=len(weights)
    for _ in range(epochs):
      gw=[0.0]*d; gb=0.0
      for row,t in zip(X,y):
       err=bias+sum(a*b for a,b in zip(row,weights))-t
       for j in range(d):gw[j]+=2*err*row[j]/n
       gb+=2*err/n
      weights=[w-lr*g for w,g in zip(weights,gw)];bias-=lr*gb
    return weights,bias

def solve(X,y,weights,bias,lr=1.0,epochs=1):
    weights=list(weights)
    for _ in range(epochs):
      for x,t in zip(X,y):
       pred=1 if sum(a*b for a,b in zip(x,weights))+bias>=0 else 0
       err=t-pred
       weights=[w+lr*err*a for w,a in zip(weights,x)];bias+=lr*err
    return weights,bias

